sql.where:
rt.deleted = 0
AND rt.mat_id = #{req.matId}
AND rt.version = #{req.version}
AND rt.status = #{req.status}

    AND rt.effective_date BETWEEN #{req.effectiveDate[0]} AND #{req.effectiveDate[1]}


    AND rt.expiry_date BETWEEN #{req.expiryDate[0]} AND #{req.expiryDate[1]}

AND rt.remark = #{req.remark}

    AND rt.create_time BETWEEN #{req.createTime[0]} AND #{req.createTime[1]}
